<script>
import {validTaskDate,taskDateStatus} from '../lib/model.js';
import {data,profile,updateData,toggleTask,notify} from '../lib/store.js';import {TASKS} from '../lib/catalog.js';import Icon from '../lib/components/Icon.svelte';
const now=new Date();const today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
function setTarget(id,value){if(value&&!validTaskDate(value))return;const dates={...$data.taskDates};if(value)dates[id]=value;else delete dates[id];updateData({...$data,taskDates:dates});notify(value?'Personal target date saved.':'Personal target date cleared.');}
let {route='profile'}=$props();let taskFilter=$state('To do');let scholarshipFilter=$state('All opportunities');
const scholarships=[{id:'ceas',title:'Engineering scholarship resources',tag:'Engineering',text:'Explore scholarships and application information through CEAS.',url:'https://ceas.uc.edu/admissions/scholarships.html'},{id:'uc',title:'UC scholarship search',tag:'University-wide',text:'Start with official university scholarship information and eligibility.',url:'https://www.uc.edu/about/financial-aid/aid/scholarships.html'},{id:'international',title:'International student resources',tag:'International',text:'Find international student support and funding information through UC International.',url:'https://www.uc.edu/about/international.html'}];
let visibleTasks=$derived(TASKS.filter(t=>taskFilter==='All tasks'||(taskFilter==='Completed'?$data.completedTasks.includes(t.id):!$data.completedTasks.includes(t.id))));
function saveScholarship(id){updateData({...$data,savedScholarships:$data.savedScholarships.includes(id)?$data.savedScholarships.filter(x=>x!==id):[...$data.savedScholarships,id]});}
</script>
{#if route==='tasks'}<div class="page-heading"><div><p class="eyebrow">One next step at a time</p><h2>Personal reminders</h2><p>Small actions that help keep your semester moving.</p></div><span class="term-pill">{$data.completedTasks.length} of {TASKS.length} complete</span></div><div class="category-chips">{#each ['To do','Completed','All tasks'] as f}<button class:active={taskFilter===f} aria-pressed={taskFilter===f} onclick={()=>taskFilter=f}>{f}</button>{/each}</div>{#each visibleTasks as t}<article class="panel task-card"><label class="task-check"><input type="checkbox" checked={$data.completedTasks.includes(t.id)} onchange={()=>toggleTask(t.id)}/><span><strong>{t.title}</strong><small>{t.description}</small><span class="badge" class:warning={taskDateStatus($data.taskDates[t.id],today)==='Overdue'||taskDateStatus($data.taskDates[t.id],today)==='Today'} class:neutral={!$data.taskDates[t.id]||$data.taskDates[t.id]>today}>{$data.completedTasks.includes(t.id)?'Completed':taskDateStatus($data.taskDates[t.id],today)}</span></span></label><label class="task-date-control">Personal target<input type="date" aria-label={`Personal target date for ${t.title}`} value={$data.taskDates[t.id]??''} onchange={e=>setTarget(t.id,e.currentTarget.value)}/></label><a class="button secondary" href={t.href}>{t.action}<Icon name="arrow" size={16}/></a></article>{/each}{#if !visibleTasks.length}<div class="empty-state panel"><span class="success-seal"><Icon name="check" size={30}/></span><h2>{taskFilter==='Completed'?'Your progress will appear here.':'A little breathing room.'}</h2><p>{taskFilter==='Completed'?'Check off a task once you’ve completed it.':'You’re caught up with the task list.'}</p></div>{/if}<p class="fine-print">Set your own target dates; these are personal reminders, not official university deadlines. Dates stay with this profile in this browser. Completing a task does not clear university holds. Use Academic services to check the official calendar.</p>
{:else if route==='scholarships'}<div class="page-heading"><div><p class="eyebrow">Make possibilities easier to find</p><h1>Scholarship resources</h1><p>Start with official information. Save a useful place to come back to.</p></div><span class="term-pill">{$data.savedScholarships.length} saved</span></div><div class="category-chips">{#each ['All opportunities','Saved resources'] as f}<button class:active={scholarshipFilter===f} aria-pressed={scholarshipFilter===f} onclick={()=>scholarshipFilter=f}>{f}</button>{/each}</div><div class="services-grid">{#each scholarships.filter(s=>scholarshipFilter==='All opportunities'||$data.savedScholarships.includes(s.id)) as s}<article class="service-card panel"><span class="tile-icon"><Icon name="star" size={24}/></span><span class="eyebrow">{s.tag}</span><h2>{s.title}</h2><p>{s.text}</p><div class="button-row"><a class="button secondary" href={s.url} target="_blank" rel="noreferrer">Visit resource<Icon name="external" size={15}/></a><button class="icon-button" class:saved={$data.savedScholarships.includes(s.id)} aria-label={`${$data.savedScholarships.includes(s.id)?'Unsave':'Save'} ${s.title}`} aria-pressed={$data.savedScholarships.includes(s.id)} onclick={()=>saveScholarship(s.id)}><Icon name="star"/></button></div></article>{/each}</div>{#if scholarshipFilter==='Saved resources'&&!$data.savedScholarships.length}<div class="empty-state panel"><h2>Keep a useful resource close.</h2><p>Use the star on a resource card to save it here.</p></div>{/if}<p class="fine-print">These are resource links, not scholarship matches or eligibility determinations. Applications take place on official websites.</p>{/if}
